
USE sales_analysis_db;

-- Day 73: Customer Revenue Concentration and Pareto Analysis

-- Query 1: Calculate total revenue generated by each customer
SELECT
    c.customer_id,
    SUM(oi.quantity * p.price) AS total_revenue,
    COUNT(DISTINCT o.order_id) AS total_orders
FROM customers c
JOIN orders o
    ON c.customer_id = o.customer_id
JOIN order_items oi
    ON o.order_id = oi.order_id
JOIN products p
    ON oi.product_id = p.product_id
GROUP BY
    c.customer_id
ORDER BY
    total_revenue DESC,
    c.customer_id;

-- Query 2: Rank customers by revenue and calculate
-- each customer's percentage of total revenue
WITH customer_revenue AS (
    SELECT
        c.customer_id,
        SUM(oi.quantity * p.price) AS total_revenue
    FROM customers c
    JOIN orders o
        ON c.customer_id = o.customer_id
    JOIN order_items oi
        ON o.order_id = oi.order_id
    JOIN products p
        ON oi.product_id = p.product_id
    GROUP BY c.customer_id
),
revenue_totals AS (
    SELECT SUM(total_revenue) AS overall_revenue
    FROM customer_revenue
)
SELECT
    cr.customer_id,
    cr.total_revenue,
    DENSE_RANK() OVER (
        ORDER BY cr.total_revenue DESC
    ) AS revenue_rank,
    ROUND(
        100.0 * cr.total_revenue /
        NULLIF(rt.overall_revenue, 0),
        2
    ) AS revenue_contribution_pct
FROM customer_revenue cr
CROSS JOIN revenue_totals rt
ORDER BY
    cr.total_revenue DESC,
    cr.customer_id;

-- Query 3: Calculate cumulative revenue contribution
WITH customer_revenue AS (
    SELECT
        c.customer_id,
        SUM(oi.quantity * p.price) AS total_revenue
    FROM customers c
    JOIN orders o
        ON c.customer_id = o.customer_id
    JOIN order_items oi
        ON o.order_id = oi.order_id
    JOIN products p
        ON oi.product_id = p.product_id
    GROUP BY c.customer_id
),
ranked_customers AS (
    SELECT
        customer_id,
        total_revenue,
        ROW_NUMBER() OVER (
            ORDER BY total_revenue DESC, customer_id
        ) AS customer_position,
        SUM(total_revenue) OVER () AS overall_revenue,
        SUM(total_revenue) OVER (
            ORDER BY total_revenue DESC, customer_id
            ROWS BETWEEN UNBOUNDED PRECEDING
            AND CURRENT ROW
        ) AS cumulative_revenue
    FROM customer_revenue
)
SELECT
    customer_id,
    total_revenue,
    customer_position,
    ROUND(
        100.0 * total_revenue /
        NULLIF(overall_revenue, 0),
        2
    ) AS individual_revenue_pct,
    ROUND(
        100.0 * cumulative_revenue /
        NULLIF(overall_revenue, 0),
        2
    ) AS cumulative_revenue_pct
FROM ranked_customers
ORDER BY customer_position;

-- Query 4: Compare the top 20% of customers with
-- the remaining customers
WITH customer_revenue AS (
    SELECT
        c.customer_id,
        SUM(oi.quantity * p.price) AS total_revenue
    FROM customers c
    JOIN orders o
        ON c.customer_id = o.customer_id
    JOIN order_items oi
        ON o.order_id = oi.order_id
    JOIN products p
        ON oi.product_id = p.product_id
    GROUP BY c.customer_id
),
ranked_customers AS (
    SELECT
        customer_id,
        total_revenue,
        ROW_NUMBER() OVER (
            ORDER BY total_revenue DESC, customer_id
        ) AS customer_position,
        COUNT(*) OVER () AS customer_count
    FROM customer_revenue
),
classified_customers AS (
    SELECT
        customer_id,
        total_revenue,
        CASE
            WHEN customer_position <=
                CEIL(customer_count * 0.20)
            THEN 'Top 20% of Customers'
            ELSE 'Remaining 80% of Customers'
        END AS customer_group
    FROM ranked_customers
)
SELECT
    customer_group,
    COUNT(*) AS customer_count,
    ROUND(SUM(total_revenue), 2) AS group_revenue,
    ROUND(
        100.0 * SUM(total_revenue) /
        NULLIF(SUM(SUM(total_revenue)) OVER (), 0),
        2
    ) AS revenue_share_pct
FROM classified_customers
GROUP BY customer_group
ORDER BY group_revenue DESC;

-- Query 5: Identify the minimum number of top customers
-- needed to reach or exceed 80% of total revenue
WITH customer_revenue AS (
    SELECT
        c.customer_id,
        SUM(oi.quantity * p.price) AS total_revenue
    FROM customers c
    JOIN orders o
        ON c.customer_id = o.customer_id
    JOIN order_items oi
        ON o.order_id = oi.order_id
    JOIN products p
        ON oi.product_id = p.product_id
    GROUP BY c.customer_id
),
ranked_customers AS (
    SELECT
        customer_id,
        total_revenue,
        ROW_NUMBER() OVER (
            ORDER BY total_revenue DESC, customer_id
        ) AS customer_position,
        SUM(total_revenue) OVER () AS overall_revenue,
        SUM(total_revenue) OVER (
            ORDER BY total_revenue DESC, customer_id
            ROWS BETWEEN UNBOUNDED PRECEDING
            AND CURRENT ROW
        ) AS cumulative_revenue
    FROM customer_revenue
),
concentration AS (
    SELECT
        customer_id,
        total_revenue,
        customer_position,
        ROUND(
            100.0 * cumulative_revenue /
            NULLIF(overall_revenue, 0),
            2
        ) AS cumulative_revenue_pct
    FROM ranked_customers
)
SELECT
    customer_id,
    total_revenue,
    customer_position,
    cumulative_revenue_pct
FROM concentration
WHERE cumulative_revenue_pct >= 80
ORDER BY customer_position
LIMIT 1;